[("Quelle activité est proposée à la voisine ?", "Préparer des étiquettes.", "Porter des pierres.", "Réparer une voiture.", "préparer les étiquettes"), ("Que fera Idriss ?", "Transmettre l’invitation.", "Acheter le terrain.", "Annuler la réunion.", "transmettrai l’invitation")],
