[("Qui a renseigné Ana ?", "L’accueil.", "Un vendeur de vélos.", "Une source anonyme uniquement.", "L’accueil m’a dit"), ("Que demande Noé ?", "La date de l’appel.", "Le prix des travaux.", "Le nom de tous les nageurs.", "quand tu as appelé")],
