[("Pourquoi plier les cartons ?", "Pour faciliter le transport.", "Pour les vendre plus cher.", "Pour cacher leur contenu.", "cela facilitera le transport"), ("Les emballages sales sont-ils inclus ?", "Non, ils sont traités séparément.", "Oui, sans exception.", "Seulement après minuit.", "Nous ne les prenons pas dans cet essai")],
