[("De quoi Victor s’excuse-t-il ?", "Du ton de son mot.", "D’avoir quitté l’appartement.", "D’avoir oublié un achat.", "Mon mot était trop sec"), ("Que préfèrent-ils pour un prochain problème ?", "En parler directement.", "Ne plus se parler.", "Changer les serrures.", "parlons-en directement")],
[("tandis que", "whereas / while"), ("au lieu de", "instead of"), ("désormais", "from now on")],
