[("Habitant", "Par qui les réservations seront-elles gérées ?"), ("Agente", "L’association vous répondra à partir de septembre."), ("Habitant", "Les tarifs ont-ils déjà été fixés ?"), ("Agente", "Non, le conseil doit encore voter."), ("Habitant", "Où sera publiée la décision ?"), ("Agente", "Dans le bulletin et sur le site de la commune.")],
[("Les tarifs sont-ils déjà décidés ?", "Non, un vote reste nécessaire.", "Oui, depuis un an.", "Ils sont toujours gratuits.", "le conseil doit encore voter"), ("Où trouvera-t-on la décision ?", "Dans le bulletin et sur le site.", "Uniquement par téléphone privé.", "Dans le train.", "Dans le bulletin et sur le site")],
[("a été transformé", "has been converted"), ("il est prévu", "it is planned"), ("tandis que", "whereas")],
"Write an announcement about a fictional renovation. Use passive forms for the changes and name the actors where accountability matters.",
