[("Quelles notifications restent actives au début ?", "Les appels familiaux et les messages de l’équipe.", "Toutes les publicités.", "Uniquement les résultats sportifs.", "les appels de ma famille et les messages de mon équipe"), ("Quel est le but de l’expérience ?", "Choisir les interruptions utiles.", "Interdire le téléphone à tous.", "Supprimer toute communication.", "choisir les interruptions utiles"), ("Quelle alerte est réactivée ?", "Une alerte de transport.", "Toutes les alertes commerciales.", "Une alerte de jeu.", "réactivé une alerte de transport")],
[("Jules", "Tu n’utilises plus ton téléphone ?"), ("Camille", "Si, mais je n’ai gardé que certaines alertes."), ("Jules", "Tu n’as rien manqué d’important ?"), ("Camille", "Non. Mon équipe peut toujours m’appeler."), ("Jules", "Personne ne s’est plaint ?"), ("Camille", "Personne. J’avais expliqué mon choix.")],
[("Camille a-t-elle abandonné son téléphone ?", "Non, elle limite les alertes.", "Oui, elle l’a vendu.", "Oui, elle ne reçoit plus d’appels.", "je n’ai gardé que certaines alertes"), ("Pourquoi l’équipe peut-elle la joindre ?", "Les appels restent possibles.", "Elle travaille au même bureau en permanence.", "Elle lit chaque publicité.", "peut toujours m’appeler")],
[("ne … que", "only"), ("ne … plus", "no longer"), ("notamment", "in particular")],
